const labels = {
  acta_grado: 'Acta de grado',
  diploma: 'Diploma',
  certificado_notas: 'Certificado de notas',
  carta_admision: 'Carta de admision'
};
return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'SION UNAC - Credencial verificable emitida: ' + (labels[item.json.type] || item.json.type),
    name: item.json.name || 'Titular',
    type: item.json.type,
    verificationCode: item.json.verificationCode,
    program: item.json.program,
    body: 'Hola ' + (item.json.name || 'Titular') + ', tu credencial de ' + (labels[item.json.type] || item.json.type) + ' fue emitida e registrada en el registro inmutable (blockchain). Codigo de verificacion: ' + item.json.verificationCode + '. Cualquier tercero puede validarla en: ' + item.json.verificationUrl,
    sentAt: new Date().toISOString()
  }
}));
